/**
 * Snapshot store: a small SQLite time-series database (Node's built-in
 * `node:sqlite`, no external dependencies) holding one row per token per
 * snapshot run. This is how the agent builds its own price/supply history —
 * the Tokenized Stocks API has no history endpoints.
 *
 * DB location: <repo>/data/snapshots.db (gitignored, regenerated by polling).
 */

import { DatabaseSync } from "node:sqlite";
import { mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import type { TokenizedStock } from "./types.ts";
import type { DexQuote } from "./dex.ts";

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
export const DEFAULT_DB_PATH = join(repoRoot, "data", "snapshots.db");
export const SNAPSHOT_JSON_DIR = join(repoRoot, "data", "snapshots");

export interface StoredSnapshot extends TokenizedStock {
  runId: number;
  takenAt: string;
}

export class SnapshotStore {
  private readonly db: DatabaseSync;

  constructor(dbPath: string = DEFAULT_DB_PATH) {
    mkdirSync(dirname(dbPath), { recursive: true });
    this.db = new DatabaseSync(dbPath);
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS snapshot_runs (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        taken_at TEXT NOT NULL
      );
      CREATE TABLE IF NOT EXISTS token_snapshots (
        run_id INTEGER NOT NULL REFERENCES snapshot_runs(id),
        taken_at TEXT NOT NULL,
        contract_address TEXT NOT NULL,
        symbol TEXT NOT NULL,
        name TEXT,
        decimals INTEGER,
        isin TEXT,
        adgm_isin TEXT,
        multiplier REAL,
        total_supply REAL,
        nav_price REAL,
        nav_price_updated_at TEXT,
        first_mint_date TEXT,
        paused_features TEXT,
        PRIMARY KEY (run_id, contract_address)
      );
      CREATE INDEX IF NOT EXISTS idx_token_snapshots_addr_time
        ON token_snapshots (contract_address, taken_at);
      CREATE TABLE IF NOT EXISTS dex_quotes (
        run_id INTEGER NOT NULL REFERENCES snapshot_runs(id),
        taken_at TEXT NOT NULL,
        contract_address TEXT NOT NULL,
        symbol TEXT NOT NULL,
        pool_address TEXT NOT NULL,
        venue TEXT NOT NULL,
        quote_symbol TEXT NOT NULL,
        spot_usd REAL NOT NULL,
        depth_usd REAL NOT NULL,
        quote_depth_usd REAL NOT NULL,
        pools_found INTEGER NOT NULL,
        PRIMARY KEY (run_id, contract_address)
      );
      CREATE TABLE IF NOT EXISTS paper_state (
        id INTEGER PRIMARY KEY CHECK (id = 1),
        state_json TEXT NOT NULL,
        updated_at TEXT NOT NULL
      );
      CREATE TABLE IF NOT EXISTS decision_records (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        run_id INTEGER,
        at TEXT NOT NULL,
        kind TEXT NOT NULL,
        trades_executed INTEGER NOT NULL,
        summary TEXT NOT NULL,
        record_json TEXT NOT NULL
      );
    `);
  }

  /** Store one full-universe snapshot. Returns the run id. */
  recordSnapshot(tokens: TokenizedStock[], takenAt = new Date()): number {
    const takenIso = takenAt.toISOString();
    const run = this.db
      .prepare("INSERT INTO snapshot_runs (taken_at) VALUES (?) RETURNING id")
      .get(takenIso) as { id: number };
    const insert = this.db.prepare(`
      INSERT INTO token_snapshots (
        run_id, taken_at, contract_address, symbol, name, decimals, isin,
        adgm_isin, multiplier, total_supply, nav_price, nav_price_updated_at,
        first_mint_date, paused_features
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);
    this.db.exec("BEGIN");
    try {
      for (const t of tokens) {
        insert.run(
          run.id,
          takenIso,
          t.contractAddress,
          t.symbol,
          t.name,
          t.decimals,
          t.isin ?? null,
          t.adgmIsin ?? null,
          t.multiplier ?? null,
          t.totalSupply ?? null,
          t.navPrice ?? null,
          t.navPriceUpdatedAt ?? null,
          t.firstMintDate ?? null,
          t.pausedFeatures ? JSON.stringify(t.pausedFeatures) : null,
        );
      }
      this.db.exec("COMMIT");
    } catch (err) {
      this.db.exec("ROLLBACK");
      throw err;
    }
    return run.id;
  }

  runCount(): number {
    const row = this.db.prepare("SELECT COUNT(*) AS n FROM snapshot_runs").get() as { n: number };
    return row.n;
  }

  /** The most recent snapshot row for every token. */
  latestSnapshots(): StoredSnapshot[] {
    const rows = this.db
      .prepare(
        `SELECT ts.* FROM token_snapshots ts
         JOIN (SELECT contract_address, MAX(taken_at) AS max_taken
               FROM token_snapshots GROUP BY contract_address) latest
           ON ts.contract_address = latest.contract_address AND ts.taken_at = latest.max_taken
         ORDER BY ts.symbol`,
      )
      .all() as Array<Record<string, unknown>>;
    return rows.map(rowToSnapshot);
  }

  /** Full stored series for one token, oldest first. */
  series(contractAddress: string): StoredSnapshot[] {
    const rows = this.db
      .prepare("SELECT * FROM token_snapshots WHERE contract_address = ? ORDER BY taken_at ASC")
      .all(contractAddress) as Array<Record<string, unknown>>;
    return rows.map(rowToSnapshot);
  }

  /** Store the DEX quotes read during one agent cycle, tied to its snapshot run. */
  recordDexQuotes(runId: number, quotes: DexQuote[], takenAt = new Date()): void {
    const takenIso = takenAt.toISOString();
    const insert = this.db.prepare(`
      INSERT INTO dex_quotes (
        run_id, taken_at, contract_address, symbol, pool_address, venue,
        quote_symbol, spot_usd, depth_usd, quote_depth_usd, pools_found
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);
    this.db.exec("BEGIN");
    try {
      for (const q of quotes) {
        insert.run(
          runId,
          takenIso,
          q.contractAddress,
          q.symbol,
          q.poolAddress,
          q.venue,
          q.quoteSymbol,
          q.spotUsd,
          q.depthUsd,
          q.quoteDepthUsd,
          q.poolsFound,
        );
      }
      this.db.exec("COMMIT");
    } catch (err) {
      this.db.exec("ROLLBACK");
      throw err;
    }
  }

  /** The most recently stored DEX quote per token, keyed by lowercase contract address. */
  latestDexQuotes(): Map<string, DexQuote> {
    const rows = this.db
      .prepare(
        `SELECT dq.* FROM dex_quotes dq
         JOIN (SELECT contract_address, MAX(taken_at) AS max_taken
               FROM dex_quotes GROUP BY contract_address) latest
           ON dq.contract_address = latest.contract_address AND dq.taken_at = latest.max_taken`,
      )
      .all() as Array<Record<string, unknown>>;
    const out = new Map<string, DexQuote>();
    for (const row of rows) {
      const quote: DexQuote = {
        contractAddress: String(row.contract_address),
        symbol: String(row.symbol),
        poolAddress: String(row.pool_address),
        venue: String(row.venue) as DexQuote["venue"],
        quoteSymbol: String(row.quote_symbol) as DexQuote["quoteSymbol"],
        spotUsd: Number(row.spot_usd),
        depthUsd: Number(row.depth_usd),
        quoteDepthUsd: Number(row.quote_depth_usd),
        poolsFound: Number(row.pools_found),
      };
      out.set(quote.contractAddress.toLowerCase(), quote);
    }
    return out;
  }

  /** Persisted paper-portfolio state (JSON), or null if none was ever saved. */
  loadPaperStateJson(): string | null {
    const row = this.db
      .prepare("SELECT state_json FROM paper_state WHERE id = 1")
      .get() as { state_json: string } | undefined;
    return row ? row.state_json : null;
  }

  savePaperStateJson(stateJson: string, updatedAt = new Date()): void {
    this.db
      .prepare(
        `INSERT INTO paper_state (id, state_json, updated_at) VALUES (1, ?, ?)
         ON CONFLICT(id) DO UPDATE SET state_json = excluded.state_json, updated_at = excluded.updated_at`,
      )
      .run(stateJson, updatedAt.toISOString());
  }

  /** Append one full decision record (the JSON is the inspectable artifact). */
  recordDecision(
    runId: number | null,
    record: { at: string; kind: string },
    recordJson: string,
    summary: string,
    tradesExecuted: number,
  ): number {
    const row = this.db
      .prepare(
        `INSERT INTO decision_records (run_id, at, kind, trades_executed, summary, record_json)
         VALUES (?, ?, ?, ?, ?, ?) RETURNING id`,
      )
      .get(runId, record.at, record.kind, tradesExecuted, summary, recordJson) as { id: number };
    return row.id;
  }

  decisionCount(): number {
    const row = this.db.prepare("SELECT COUNT(*) AS n FROM decision_records").get() as { n: number };
    return row.n;
  }

  latestDecision(): {
    id: number;
    runId: number | null;
    at: string;
    kind: string;
    tradesExecuted: number;
    summary: string;
    recordJson: string;
  } | null {
    const row = this.db
      .prepare("SELECT * FROM decision_records ORDER BY id DESC LIMIT 1")
      .get() as Record<string, unknown> | undefined;
    if (!row) return null;
    return {
      id: Number(row.id),
      runId: row.run_id === null ? null : Number(row.run_id),
      at: String(row.at),
      kind: String(row.kind),
      tradesExecuted: Number(row.trades_executed),
      summary: String(row.summary),
      recordJson: String(row.record_json),
    };
  }

  close(): void {
    this.db.close();
  }
}

function rowToSnapshot(row: Record<string, unknown>): StoredSnapshot {
  const num = (v: unknown): number | undefined => (typeof v === "number" ? v : undefined);
  const str = (v: unknown): string | undefined => (typeof v === "string" ? v : undefined);
  return {
    runId: Number(row.run_id),
    takenAt: String(row.taken_at),
    contractAddress: String(row.contract_address),
    symbol: String(row.symbol),
    name: String(row.name ?? ""),
    decimals: Number(row.decimals ?? 0),
    isin: str(row.isin),
    adgmIsin: str(row.adgm_isin),
    multiplier: num(row.multiplier),
    totalSupply: num(row.total_supply),
    navPrice: num(row.nav_price),
    navPriceUpdatedAt: str(row.nav_price_updated_at),
    firstMintDate: str(row.first_mint_date),
    pausedFeatures: row.paused_features ? (JSON.parse(String(row.paused_features)) as string[]) : undefined,
  };
}
